def combinations_colors(colors, n):
    result = []

    def generate(current_combination, length_left):
        if length_left == 0:
            result.append(tuple(current_combination))
            return

        for color in colors:
            current_combination.append(color)
            generate(current_combination, length_left - 1)
            current_combination.pop()

    generate([], n)
    return result
